// A handful of named text roles, defined once, instead of hand-tuning
// fontSize/weight/letterSpacing per component every time a request comes in
// — which is how this file ended up with the same "muted step subtitle"
// re-implemented at 16/17/18/19px and the same "small uppercase card label"
// re-implemented at 10/11/13/14px across dozens of call sites. Color is
// deliberately NOT included here (stage/context color stays a per-call-site
// override) — spread the role, then override color: `{ ...TYPE.stepSubtitle,
// color: someColor }`. Small and growing on purpose: add a role here only
// once the same shape has genuinely repeated 3+ times, not preemptively.
const TYPE: Record<string, React.CSSProperties> = {
  // Muted italic one-liner shown under a step's H1 (STEP_GOALS.<mod>[n]).
  stepSubtitle: {
    fontFamily: "'Caveat', 'Comic Sans MS', cursive, system-ui",
    fontSize: 19, fontStyle: 'italic' as const, lineHeight: 1.4,
  },
  // Small uppercase eyebrow label at the top of a postcard/summary card
  // ("YOUR HYPOTHESIS", "YOUR CALL", "Feature 1", ...).
  postcardLabel: {
    fontFamily: '"Arial Black", "Arial Bold", Gadget, sans-serif',
    fontSize: 11, fontWeight: 900 as const, letterSpacing: 0.4,
    textTransform: 'uppercase' as const,
  },
};

// Hand-drawn "wobble" variants — mismatched-corner borderRadius + a slight rotate,
// cycled by index (i % 4) to make repeated cards/chips look hand-drawn rather than
// machine-stamped. Shared here since it's now used at 10+ call sites across
// Idea/Hone/Validate/Shape/Done (individual call sites used to inline their own
// copy of this same array — new call sites should use this shared one instead).
const WOBBLE_VARIANTS = [
  { borderRadius: '9px 12px 8px 13px / 12px 8px 13px 9px', rotate: -0.5 },
  { borderRadius: '13px 8px 12px 9px / 9px 13px 8px 12px', rotate: 0.6 },
  { borderRadius: '8px 13px 9px 12px / 13px 9px 12px 8px', rotate: -0.4 },
  { borderRadius: '12px 9px 13px 8px / 8px 12px 9px 13px', rotate: 0.5 },
];

const MULTI_SEP = '|||';
const FIELD_SEP = '~~'; // internal field separator within one persona entry

// Extract the human-readable composed text from a single serialised persona segment
const parsePersonaText = (seg: string): string => seg.split(FIELD_SEP)[0];

// Return a display-friendly string for all saved personas joined by ·
const parseWhoDisplay = (v: string): string =>
  v.split(MULTI_SEP).filter(Boolean).map(parsePersonaText).filter(t => t.trim().length > 2).join(' · ');

// Extract plain text from a severity problem entry ("text~~severity")
const parseProblemText = (seg: string): string => seg.split(FIELD_SEP)[0];

// Human-readable summary of all saved problems
const parseProblemDisplay = (v: string): string =>
  v.split(MULTI_SEP).filter(Boolean).map(parseProblemText).filter(t => t.trim().length > 2).join(' · ');

// Pure utility — parse key_insights text into per-question blocks
const parseInsights = (text: string): { question: string; signals: string[]; quote: string }[] => {
  if (!text) return [];
  const chunks = text.split(/\nQ\d+:|\n\nQ\d+:/);
  return chunks.filter(Boolean).map(chunk => {
    const lines = chunk.trim().split('\n');
    const question = lines[0]?.replace(/^Q\d+:\s*/, '').trim() || '';
    const body = lines.slice(1).join('\n').trim();
    const sigMatch = body.match(/^\[([^\]]+)\]/);
    const signals = sigMatch ? sigMatch[1].split(',').map(s => s.trim()).filter(Boolean) : [];
    const quote = body.replace(/^\[[^\]]+\]\s*/, '').trim();
    return { question, signals, quote };
  }).filter(c => c.question || c.signals.length || c.quote);
};

