// ── Animation ──────────────────────────────────────────────────────────────

function useStepAnimation() {
  useEffect(() => {
    const id = 'work-anim';
    if (document.getElementById(id)) return;
    const s = document.createElement('style');
    s.id = id;
    s.textContent = `@keyframes wup{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:translateY(0)}}@keyframes tickPop{0%{opacity:0;transform:scale(.3) rotate(-20deg)}60%{opacity:1;transform:scale(1.25) rotate(6deg)}100%{opacity:1;transform:scale(1) rotate(0deg)}}@keyframes stepIntroIn{from{opacity:0;transform:translateY(-4px)}to{opacity:1;transform:translateY(0)}}@keyframes stepIntroOut{from{opacity:1}to{opacity:0}}@keyframes stepFwdIn{from{opacity:0;transform:translateX(18px)}to{opacity:1;transform:translateX(0)}}@keyframes stepBackIn{from{opacity:0;transform:translateX(-18px)}to{opacity:1;transform:translateX(0)}}@media (prefers-reduced-motion: reduce){.step-intro,.step-nav{animation:none !important}}@keyframes milestoneToastIn{from{opacity:0;transform:translate(-50%,-10px)}to{opacity:1;transform:translate(-50%,0)}}@keyframes msConfettiFall{0%{transform:translateY(-24px) rotate(0deg);opacity:1}80%{opacity:1}100%{transform:translateY(110vh) rotate(600deg);opacity:0}}`;
    document.head.appendChild(s);
  }, []);
}

// ── Style helpers ──────────────────────────────────────────────────────────

const inp: React.CSSProperties = {
  width: '100%', padding: '12px 14px',
  border: `1.5px solid ${BORDER}`, borderRadius: 10,
  fontSize: 15, outline: 'none', background: '#fff',
  color: USER_INPUT_COLOR, boxSizing: 'border-box', lineHeight: 1.6,
  fontFamily: 'inherit', transition: 'border-color .18s',
};
const ta = (h = 90): React.CSSProperties => ({ ...inp, minHeight: h, resize: 'vertical' as const });
const lbl: React.CSSProperties = { fontSize: 14, fontWeight: 800, color: '#3a3a3c', display: 'flex', alignItems: 'flex-start', gap: 8, marginBottom: 8 };
const col: React.CSSProperties = { display: 'flex', flexDirection: 'column', gap: 20 };

// Manual-entry fallback for a chip row — controlled directly off the same
// field the chips write to, so typing here just IS "picking a custom value".
// Defined at module scope (not inline inside a step's render function) so its
// component identity is stable across re-renders — otherwise React remounts
// the <input> on every keystroke and focus is lost after the first character.
const GoalCustomInput = ({ value, onChange, placeholder, accent }: { value: string; onChange: (v: string) => void; placeholder: string; accent: string }) => (
  <input
    type="text"
    value={value}
    onChange={e => onChange(e.target.value)}
    placeholder={placeholder}
    style={{
      padding: '7px 13px', borderRadius: 20, fontSize: 13, fontWeight: 600,
      border: `1.5px dashed ${value ? accent : BORDER2}`, background: value ? `${accent}0c` : '#fff',
      color: value ? accent : T2, outline: 'none', minWidth: 150, fontFamily: 'inherit',
    }}
    onFocus={e => (e.currentTarget.style.borderColor = accent)}
    onBlur={e => (e.currentTarget.style.borderColor = e.currentTarget.value ? accent : BORDER2)}
  />
);

// ── Idea context (avoids prop-drilling ideaId into every field) ────────────

const IdeaIdCtx = React.createContext<string>('');

// ── Ask community button (self-contained, drop next to any field) ──────────

function AskCommunityButton({ ask }: { ask: string }) {
  const ideaId = React.useContext(IdeaIdCtx);
  const [open, setOpen]         = useState(false);
  const [question, setQ]        = useState('');
  const [posting, setPosting]   = useState(false);
  const [posted, setPosted]     = useState(false);
  const [focused, setFocused]   = useState(false);
  const [replyCount, setReplyCount] = useState(0);
  const taRef = React.useRef<HTMLTextAreaElement>(null);

  // Storage key for tracking when this step was last asked and how many posts existed then
  const storageKey = ideaId ? `mvpclub_ask_${ideaId}_${ask.slice(0, 30)}` : null;

  // On mount, check if we've previously asked this question and if new posts exist
  React.useEffect(() => {
    if (!storageKey || !ideaId) return;
    const stored = localStorage.getItem(storageKey);
    if (!stored) return;
    const { postCountAtAsk } = JSON.parse(stored);
    communityApi.getIdeaPosts(ideaId)
      .then(res => {
        const currentCount: number = res.data.posts?.length ?? 0;
        const newReplies = Math.max(0, currentCount - postCountAtAsk);
        setReplyCount(newReplies);
      })
      .catch(() => {});
  }, [storageKey, ideaId]);

  if (!ideaId) return null;

  const handlePost = async () => {
    if (!question.trim()) return;
    setPosting(true);
    try {
      // Snapshot current post count so we can track new replies later
      let countBefore = 0;
      try {
        const r = await communityApi.getIdeaPosts(ideaId);
        countBefore = r.data.posts?.length ?? 0;
      } catch { /* ignore */ }

      await communityApi.addIdeaPost(ideaId, {
        content: `💬 **Re: ${ask}**\n\n${question.trim()}`,
        post_type: 'question',
      });

      // Store the post count at time of asking so we can detect replies
      if (storageKey) {
        localStorage.setItem(storageKey, JSON.stringify({ postCountAtAsk: countBefore + 1 }));
      }

      setPosted(true);
      setQ('');
      setReplyCount(0);
      setTimeout(() => { setPosted(false); setOpen(false); }, 2200);
    } catch { /* silent */ } finally { setPosting(false); }
  };

  const clearBadge = () => setReplyCount(0);

  return (
    <>
      <div style={{ position: 'relative', display: 'inline-flex', marginLeft: 'auto', flexShrink: 0 }}>
        <button
          onClick={e => { e.preventDefault(); setOpen(true); setPosted(false); clearBadge(); }}
          title="Ask the community"
          style={{
            background: replyCount > 0 ? '#eff6ff' : '#f0f4ff',
            border: `1.5px solid ${replyCount > 0 ? '#2563eb60' : '#2563eb25'}`,
            borderRadius: 8, padding: '3px 10px',
            fontSize: 11, fontWeight: 700, color: '#2563eb',
            cursor: 'pointer', display: 'inline-flex', alignItems: 'center', gap: 5,
            transition: 'all .15s', whiteSpace: 'nowrap' as const,
          }}
          onMouseEnter={e => { e.currentTarget.style.background = '#dbeafe'; e.currentTarget.style.borderColor = '#2563eb60'; }}
          onMouseLeave={e => { e.currentTarget.style.background = replyCount > 0 ? '#eff6ff' : '#f0f4ff'; e.currentTarget.style.borderColor = replyCount > 0 ? '#2563eb60' : '#2563eb25'; }}
        >
          💬 {replyCount > 0 ? `${replyCount} new repl${replyCount === 1 ? 'y' : 'ies'}` : 'Ask community'}
        </button>
        {replyCount > 0 && (
          <span style={{
            position: 'absolute', top: -5, right: -5,
            width: 14, height: 14, borderRadius: '50%',
            background: '#dc2626', border: '2px solid #fff',
            fontSize: 8, fontWeight: 800, color: '#fff',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
          }}>
            {replyCount > 9 ? '9+' : replyCount}
          </span>
        )}
      </div>

      {open && (
        <div
          onClick={e => { if (e.target === e.currentTarget) setOpen(false); }}
          style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,.4)', zIndex: 2000, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 24, backdropFilter: 'blur(6px)' }}
        >
          <div style={{ background: '#fff', borderRadius: 24, width: '100%', maxWidth: 480, boxShadow: '0 32px 80px rgba(0,0,0,.22)', animation: 'wup .2s ease', overflow: 'hidden' }}>
            {posted ? (
              <div style={{ textAlign: 'center', padding: '52px 32px' }}>
                <div style={{ fontSize: 52, marginBottom: 14 }}>🎉</div>
                <div style={{ fontSize: 18, fontWeight: 800, color: '#059669', marginBottom: 6 }}>Posted to community!</div>
                <div style={{ fontSize: 13, color: '#6e6e73', lineHeight: 1.55 }}>Other founders at your stage can now weigh in. Come back to check the replies!</div>
              </div>
            ) : (
              <>
                {/* Header */}
                <div style={{ padding: '22px 24px 18px', borderBottom: '1px solid #f5f5f7' }}>
                  <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between' }}>
                    <div>
                      <div style={{ fontSize: 18, fontWeight: 800, letterSpacing: -.4, color: '#111', marginBottom: 8 }}>Ask the community ❓</div>
                      <div style={{ display: 'inline-flex', alignItems: 'center', gap: 6, background: '#eff6ff', border: '1.5px solid #bfdbfe', borderRadius: 8, padding: '4px 12px', fontSize: 12, color: '#1e40af', fontWeight: 600 }}>
                        📍 {ask}
                      </div>
                    </div>
                    <button onClick={() => setOpen(false)} style={{ background: '#f5f5f7', border: 'none', borderRadius: '50%', width: 32, height: 32, fontSize: 15, cursor: 'pointer', color: '#6e6e73', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0, marginLeft: 12 }}>✕</button>
                  </div>
                </div>

                {/* Compose */}
                <div style={{ padding: '20px 24px 24px' }}>
                  <div style={{
                    border: `2px solid ${focused ? '#2563eb' : '#e5e5ea'}`,
                    borderRadius: 16, overflow: 'hidden',
                    boxShadow: focused ? '0 0 0 4px rgba(37,99,235,.1)' : 'none',
                    transition: 'all .2s', marginBottom: 16,
                  }}>
                    <textarea
                      ref={taRef}
                      value={question}
                      onChange={e => setQ(e.target.value)}
                      onFocus={() => setFocused(true)}
                      onBlur={() => setFocused(false)}
                      onKeyDown={e => { if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) handlePost(); }}
                      placeholder={`What specifically do you need help with on "${ask}"? Be as specific as possible — the more context you give, the better the answers.`}
                      autoFocus
                      rows={4}
                      style={{
                        width: '100%', boxSizing: 'border-box',
                        padding: '14px 16px',
                        border: 'none', outline: 'none',
                        resize: 'none' as const,
                        fontSize: 14, lineHeight: 1.7,
                        fontFamily: 'inherit', color: USER_INPUT_COLOR,
                        background: 'transparent',
                      }}
                    />
                    <div style={{ padding: '8px 14px 12px', display: 'flex', justifyContent: 'flex-end' }}>
                      <span style={{ fontSize: 10, color: question.length > 450 ? '#dc2626' : '#c7c7cc', fontWeight: 500 }}>
                        {question.length}/500
                      </span>
                    </div>
                  </div>

                  <div style={{ display: 'flex', gap: 8 }}>
                    <button onClick={() => setOpen(false)} style={{ flex: 1, padding: '12px', borderRadius: 12, border: '1.5px solid #e5e5ea', background: '#fff', color: '#6e6e73', fontSize: 13, fontWeight: 600, cursor: 'pointer' }}>
                      Cancel
                    </button>
                    <button
                      onClick={handlePost}
                      disabled={!question.trim() || posting}
                      style={{
                        flex: 2, padding: '12px', borderRadius: 12, border: 'none',
                        background: question.trim() && !posting ? '#2563eb' : '#f0f0f0',
                        color: question.trim() && !posting ? '#fff' : '#b0b0b8',
                        fontSize: 13, fontWeight: 700,
                        cursor: question.trim() && !posting ? 'pointer' : 'default',
                        transition: 'all .15s',
                      }}
                    >
                      {posting ? 'Posting…' : '💬 Post to community'}
                    </button>
                  </div>
                  <div style={{ fontSize: 10, color: '#c7c7cc', textAlign: 'center' as const, marginTop: 8 }}>⌘↵ to post</div>
                </div>
              </>
            )}
          </div>
        </div>
      )}
    </>
  );
}

// ── Primitives ─────────────────────────────────────────────────────────────

// Marker-written question style — same treatment as the Validation Goal
// Builder's questions (Arial Black, dark navy, tight tracking) plus a
// hand-drawn underline in the given accent colour. Reusable anywhere a
// "question" should read as bold/marker-style rather than plain text.
function MarkerQuestion({ children, accent = '#2563eb' }: { children: React.ReactNode; accent?: string }) {
  return (
    <span style={{ display: 'inline-block' }}>
      <span style={{
        fontSize: 22, fontWeight: 900, color: '#0f172a',
        fontFamily: "'Playfair Display', Georgia, serif",
        letterSpacing: -0.5, lineHeight: 1.2,
      }}>
        {children}
      </span>
      <svg viewBox="0 0 400 8" width="100%" height="8" style={{ display: 'block', marginTop: 3, maxWidth: 380 }}>
        <path d="M0,4 C40,1 80,7 120,4 C160,1 200,7 240,4 C280,1 320,7 360,4 C380,2 395,5 400,4" fill="none" stroke={accent} strokeWidth="2.5" strokeLinecap="round" />
      </svg>
    </span>
  );
}

function FieldLabel({ n, children, ask, accent }: { n?: number; children: React.ReactNode; ask?: string; accent?: string }) {
  return (
    <label style={{ ...lbl, justifyContent: 'space-between' }}>
      <span style={{ display: 'flex', alignItems: 'flex-start', gap: 8 }}>
        {n !== undefined && (
          <span style={{ width: 22, height: 22, borderRadius: '50%', background: '#ededf0', border: `1px solid ${BORDER}`, color: '#6e6e73', fontSize: 10, fontWeight: 800, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0, marginTop: 1 }}>{n}</span>
        )}
        <span>{accent ? <MarkerQuestion accent={accent}>{children}</MarkerQuestion> : children}</span>
      </span>
      {ask && <AskCommunityButton ask={ask} />}
    </label>
  );
}

// Reusable inline editor for any plain-text stage_entries value shown read-only
// elsewhere in the UI (e.g. carry-forward summary cards). Click the pencil to
// rewrite the text in place; click the trash icon (with a one-tap confirm) to
// clear it back to empty — same as if the field had never been filled in.
// Deliberately scoped to plain free-text fields; fields with a serialised
// format (MULTI_SEP/FIELD_SEP-joined, e.g. whoExactly) should keep using their
// dedicated structured editor instead of raw text edit here.
function EditableText({ value, placeholder, onSave, onDelete, accent, multiline = false, textStyle, canDelete = true }: {
  value: string;
  placeholder?: string;
  onSave: (v: string) => void;
  onDelete?: () => void;
  accent: string;
  multiline?: boolean;
  textStyle?: React.CSSProperties;
  canDelete?: boolean;
}) {
  const [editing, setEditing] = React.useState(false);
  const [draft, setDraft] = React.useState(value);
  const [confirmDelete, setConfirmDelete] = React.useState(false);

  React.useEffect(() => { if (!editing) setDraft(value); }, [value, editing]);

  const commit = () => { onSave(draft.trim()); setEditing(false); setConfirmDelete(false); };
  const cancel = () => { setDraft(value); setEditing(false); setConfirmDelete(false); };
  const doDelete = () => { (onDelete || (() => onSave('')))(); setEditing(false); setConfirmDelete(false); };

  if (editing) {
    return (
      <div style={{ display: 'flex', flexDirection: 'column', gap: 6, width: '100%' }}>
        {multiline ? (
          <textarea
            autoFocus
            value={draft}
            placeholder={placeholder}
            onChange={e => setDraft(e.target.value)}
            style={{ ...textStyle, width: '100%', boxSizing: 'border-box' as const, border: `1.5px solid ${accent}`, borderRadius: 8, padding: '8px 10px', fontFamily: 'inherit', resize: 'vertical' as const, minHeight: 60 }}
          />
        ) : (
          <input
            autoFocus
            value={draft}
            placeholder={placeholder}
            onChange={e => setDraft(e.target.value)}
            style={{ ...textStyle, width: '100%', boxSizing: 'border-box' as const, border: `1.5px solid ${accent}`, borderRadius: 8, padding: '8px 10px', fontFamily: 'inherit' }}
          />
        )}
        <div style={{ display: 'flex', gap: 8 }}>
          <button type="button" onClick={commit} style={{ border: 'none', background: accent, color: '#fff', fontSize: 11, fontWeight: 700, borderRadius: 6, padding: '5px 10px', cursor: 'pointer', fontFamily: 'inherit' }}>Save</button>
          <button type="button" onClick={cancel} style={{ border: `1px solid ${BORDER}`, background: '#fff', color: '#6e6e73', fontSize: 11, fontWeight: 700, borderRadius: 6, padding: '5px 10px', cursor: 'pointer', fontFamily: 'inherit' }}>Cancel</button>
        </div>
      </div>
    );
  }

  return (
    <div style={{ display: 'flex', alignItems: 'flex-start', gap: 6, width: '100%' }}>
      <div style={{ ...textStyle, flex: 1 }}>
        {value || <span style={{ color: '#a1a1aa', fontStyle: 'italic' as const, fontWeight: 400 }}>{placeholder || 'Not set'}</span>}
      </div>
      <div style={{ display: 'flex', gap: 2, flexShrink: 0 }}>
        <button type="button" title="Edit" onClick={() => setEditing(true)} style={{ border: 'none', background: 'none', cursor: 'pointer', fontSize: 12, padding: 2, opacity: 0.5, lineHeight: 1 }}>✏️</button>
        {canDelete && (confirmDelete ? (
          <>
            <button type="button" title="Confirm delete" onClick={doDelete} style={{ border: 'none', background: 'none', cursor: 'pointer', fontSize: 10, padding: '2px 4px', color: '#dc2626', fontWeight: 800, fontFamily: 'inherit' }}>Delete?</button>
            <button type="button" title="Cancel" onClick={() => setConfirmDelete(false)} style={{ border: 'none', background: 'none', cursor: 'pointer', fontSize: 12, padding: 2, opacity: 0.5, lineHeight: 1 }}>✕</button>
          </>
        ) : (
          <button type="button" title="Clear" onClick={() => setConfirmDelete(true)} style={{ border: 'none', background: 'none', cursor: 'pointer', fontSize: 12, padding: 2, opacity: 0.5, lineHeight: 1 }}>🗑️</button>
        ))}
      </div>
    </div>
  );
}


// Reusable hand-drawn "whiteboard" toggle chip — wobble via WOBBLE_VARIANTS[index % 4]
// plus Caveat handwriting font, matching the chip treatment used throughout
// Idea/Hone. Used for the many flat toggle-chip lists across Validate/Shape/Done.
function WobbleChip({ index, active, color, onClick, children, size = 'md' }: { index: number; active: boolean; color: string; onClick: () => void; children: React.ReactNode; size?: 'sm' | 'md' }) {
  const w = WOBBLE_VARIANTS[index % 4];
  return (
    <button
      type="button"
      onClick={onClick}
      style={{
        padding: size === 'sm' ? '5px 12px' : '7px 14px',
        fontFamily: "'Caveat', 'Comic Sans MS', cursive, system-ui",
        fontSize: size === 'sm' ? 15 : 17,
        fontWeight: active ? 700 : 600,
        cursor: 'pointer',
        border: `${active ? 2.5 : 2}px solid ${active ? color : '#d8d8d8'}`,
        background: active ? `${color}12` : '#fffdf8',
        color: active ? color : '#555',
        boxShadow: '1px 2px 0 rgba(0,0,0,0.05)',
        borderRadius: w.borderRadius,
        transform: `rotate(${w.rotate}deg)`,
        transition: 'all .12s',
      }}
    >
      {children}
    </button>
  );
}

// Marker-ink chip for the whiteboard-styled Shape Step 2 ("What will you
// build?") — deliberately distinct from WobbleChip's postcard look (Kalam
// font instead of Caveat, dashed hand-drawn border instead of a solid one,
// no per-chip rotation) so this one step reads as a genuinely different
// surface, the way a real whiteboard session would.
function WhiteboardChip({ active, color, onClick, children, size = 'md' }: { active: boolean; color: string; onClick: () => void; children: React.ReactNode; size?: 'sm' | 'md' }) {
  return (
    <button
      type="button"
      onClick={onClick}
      style={{
        padding: size === 'sm' ? '5px 13px' : '7px 15px',
        fontFamily: "'Kalam', cursive",
        fontSize: size === 'sm' ? 13 : 14.5,
        fontWeight: 700,
        cursor: 'pointer',
        border: `2px ${active ? 'solid' : 'dashed'} ${color}`,
        background: active ? color : '#fff',
        color: active ? '#fff' : color,
        borderRadius: 100,
        boxShadow: active ? '1.5px 2px 0 rgba(0,0,0,.12)' : 'none',
        transition: 'all .12s',
      }}
    >
      {children}
    </button>
  );
}

function Callout({ type = 'example', tag, children }: { type?: 'example' | 'warn' | 'info' | 'green'; tag?: string; children: React.ReactNode }) {
  const cfg = {
    example: { bg: '#f5f3ff', bl: '#7c3aed', tc: '#3b0764', tag: '#7c3aed' },
    warn:    { bg: '#fffbeb', bl: '#d97706', tc: '#78350f', tag: '#d97706' },
    info:    { bg: '#eff6ff', bl: '#2563eb', tc: '#1e3a8a', tag: '#2563eb' },
    green:   { bg: '#f0fdf4', bl: '#059669', tc: '#064e3b', tag: '#059669' },
  }[type];
  return (
    <div style={{ borderLeft: `4px solid ${cfg.bl}`, background: cfg.bg, borderRadius: '0 10px 10px 0', padding: '12px 16px', fontSize: 14, lineHeight: 1.65 }}>
      {tag && <div style={{ fontSize: 10, fontWeight: 800, letterSpacing: 1.2, textTransform: 'uppercase' as const, color: cfg.tag, marginBottom: 5 }}>{tag}</div>}
      <div style={{ color: cfg.tc, fontWeight: 500 }}>{children}</div>
    </div>
  );
}

// ── BMC block label ────────────────────────────────────────────────────────

