// ── Multi-entry shell ─────────────────────────────────────────────────────

function MultiEntryShell({
  fieldValue,
  onFieldChange,
  renderBuilder,
  renderCard,
  addLabel,
  accentColor = '#2563eb',
  isEntryValid,
}: {
  fieldValue: string;
  onFieldChange: (v: string) => void;
  renderBuilder: (value: string, onChange: (v: string) => void, builderKey: number) => React.ReactNode;
  renderCard: (entry: string, index: number, onRemove: () => void) => React.ReactNode;
  addLabel: string;
  accentColor?: string;
  isEntryValid: (v: string) => boolean;
}) {
  const [savedEntries, setSavedEntries] = React.useState<string[]>([]);
  const [draft, setDraft] = React.useState('');
  const [builderKey, setBuilderKey] = React.useState(0);
  const initialized = React.useRef(false);

  // Parse existing field value on first non-empty load
  React.useEffect(() => {
    if (initialized.current || !fieldValue) return;
    initialized.current = true;
    const parts = fieldValue.split(MULTI_SEP).filter(Boolean);
    if (parts.length > 1) {
      setSavedEntries(parts.slice(0, -1));
      setDraft(parts[parts.length - 1]);
    } else if (parts.length === 1) {
      setDraft(parts[0]);
    }
  }, [fieldValue]);

  // Sync state → parent field whenever entries or draft change
  React.useEffect(() => {
    if (!initialized.current && !draft && savedEntries.length === 0) return;
    const all = savedEntries.length > 0
      ? (draft ? [...savedEntries, draft].join(MULTI_SEP) : savedEntries.join(MULTI_SEP))
      : draft;
    onFieldChange(all);
  }, [savedEntries, draft]);

  const addEntry = () => {
    if (!isEntryValid(draft)) return;
    setSavedEntries(prev => [...prev, draft]);
    setDraft('');
    setBuilderKey(k => k + 1);
  };

  const removeEntry = (i: number) => {
    setSavedEntries(prev => prev.filter((_, j) => j !== i));
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
      {savedEntries.map((entry, i) => renderCard(entry, i, () => removeEntry(i)))}
      {renderBuilder(draft, setDraft, builderKey)}
      {isEntryValid(draft) && (
        <button
          onClick={addEntry}
          style={{
            padding: '12px 16px', borderRadius: 10,
            border: `2px dashed ${accentColor}50`,
            background: `${accentColor}06`, color: accentColor,
            fontSize: 13, fontWeight: 600, cursor: 'pointer',
            fontFamily: 'inherit', transition: 'all .15s', textAlign: 'left' as const,
          }}
          onMouseEnter={e => { e.currentTarget.style.background = `${accentColor}12`; e.currentTarget.style.borderColor = `${accentColor}80`; }}
          onMouseLeave={e => { e.currentTarget.style.background = `${accentColor}06`; e.currentTarget.style.borderColor = `${accentColor}50`; }}
        >
          + {addLabel}
        </button>
      )}
    </div>
  );
}

function PersonaEntryCard({ entry, index, onRemove }: { entry: string; index: number; onRemove: () => void }) {
  const c = STAGE_COLORS.hone;
  return (
    <div key={index} style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '12px 14px', borderRadius: 10, background: '#eff6ff', border: `1.5px solid ${c}30`, animation: 'wup .15s ease' }}>
      <span style={{ fontSize: 18, flexShrink: 0 }}>🎯</span>
      <div style={{ flex: 1 }}>
        <div style={{ fontSize: 9, fontWeight: 800, letterSpacing: 1, textTransform: 'uppercase' as const, color: c, marginBottom: 2 }}>Persona {index + 1}</div>
        <div style={{ fontSize: 13, fontWeight: 600, color: '#1e3a8a', lineHeight: 1.4 }}>{entry}</div>
      </div>
      <button onClick={onRemove} style={{ background: 'none', border: 'none', cursor: 'pointer', color: '#b0b0b8', fontSize: 15, padding: 4, lineHeight: 1, flexShrink: 0 }}>✕</button>
    </div>
  );
}

function ProblemEntryCard({ entry, index, onRemove }: { entry: string; index: number; onRemove: () => void }) {
  const c = STAGE_COLORS.hone;
  return (
    <div key={index} style={{ display: 'flex', alignItems: 'flex-start', gap: 10, padding: '12px 14px', borderRadius: 10, background: '#eff6ff', border: `1.5px solid ${c}30`, animation: 'wup .15s ease' }}>
      <span style={{ fontSize: 18, flexShrink: 0, marginTop: 1 }}>⚠️</span>
      <div style={{ flex: 1 }}>
        <div style={{ fontSize: 9, fontWeight: 800, letterSpacing: 1, textTransform: 'uppercase' as const, color: c, marginBottom: 3 }}>Problem {index + 1}</div>
        <div style={{ fontSize: 13, color: '#1e3a8a', lineHeight: 1.55, fontStyle: 'italic' }}>{entry}</div>
      </div>
      <button onClick={onRemove} style={{ background: 'none', border: 'none', cursor: 'pointer', color: '#b0b0b8', fontSize: 15, padding: 4, lineHeight: 1, flexShrink: 0 }}>✕</button>
    </div>
  );
}

function ConsequenceEntryCard({ entry, index, onRemove }: { entry: string; index: number; onRemove: () => void }) {
  const m = entry.match(/^\[(.+?)\] (.+)$/);
  const typeLabel = m ? m[1] : '';
  const text = m ? m[2] : entry;
  const typeConf = [
    { label: 'Wasted time', icon: '⏰', color: '#7c3aed' },
    { label: 'Financial drain', icon: '💸', color: '#059669' },
    { label: 'Missed opportunity', icon: '📉', color: '#2563eb' },
    { label: 'Grinding frustration', icon: '😤', color: '#d97706' },
    { label: 'It compounds', icon: '🔄', color: '#dc2626' },
  ].find(c => c.label === typeLabel);
  const c = typeConf?.color ?? '#6e6e73';
  return (
    <div key={index} style={{ display: 'flex', alignItems: 'flex-start', gap: 10, padding: '12px 14px', borderRadius: 10, background: `${c}07`, border: `1.5px solid ${c}30`, animation: 'wup .15s ease' }}>
      <span style={{ fontSize: 18, flexShrink: 0, marginTop: 1 }}>{typeConf?.icon ?? '⚡'}</span>
      <div style={{ flex: 1 }}>
        <div style={{ fontSize: 9, fontWeight: 800, letterSpacing: 1, textTransform: 'uppercase' as const, color: c, marginBottom: 3 }}>{typeLabel || `Consequence ${index + 1}`}</div>
        <div style={{ fontSize: 13, color: '#1d1d1f', lineHeight: 1.55, fontStyle: 'italic' }}>{text}</div>
      </div>
      <button onClick={onRemove} style={{ background: 'none', border: 'none', cursor: 'pointer', color: '#b0b0b8', fontSize: 15, padding: 4, lineHeight: 1, flexShrink: 0 }}>✕</button>
    </div>
  );
}

function StepBars({ mod, step }: { mod: Mod; step: number }) {
  const c = STAGE_COLORS[mod];
  const total = META[mod].steps;
  return (
    <div style={{ marginBottom: 20 }}>
      {/* Step pill — mirrors explainer's "STAGE N OF 5" but softer (outlined, not solid) */}
      <div style={{ display: 'inline-flex', alignItems: 'center', background: `${c}10`, border: `1.5px solid ${c}35`, color: c, fontSize: 11, fontWeight: 700, letterSpacing: '.1em', textTransform: 'uppercase' as const, padding: '5px 14px', borderRadius: 999, marginBottom: 12 }}>
        Step {step + 1} of {total}
      </div>
      {/* Progress bars */}
      <div style={{ display: 'flex', gap: 5 }}>
        {Array.from({ length: total }).map((_, i) => (
          <div key={i} style={{ flex: 1, height: 3, borderRadius: 2, background: i < step ? c : i === step ? `${c}55` : BORDER, transition: 'background .3s' }} />
        ))}
      </div>
    </div>
  );
}

function ModBadge({ mod }: { mod: Mod }) {
  const c = STAGE_COLORS[mod];
  return (
    <span style={{ display: 'inline-block', padding: '4px 10px', borderRadius: 20, fontSize: 10, fontWeight: 700, letterSpacing: '.08em', textTransform: 'uppercase' as const, background: `${c}10`, border: `1px solid ${c}25`, color: c, marginBottom: 8 }}>
      {META[mod].icon} {META[mod].label}
    </span>
  );
}

// Small fixed persona icon for the agent's prompts — Bauhaus-geometric
// portrait (bold primary-tone polygons), picked from the "more human, more
