// ── Configurable outreach messages: build-your-own, use-current, or pick a pre-seeded template ──
// Every message below is written generically (audience-neutral) and rendered per-idea via the
// {AUDIENCE}/{Audience}/{AUDIENCE_ONE}/{A_AUDIENCE_ONE} tokens, so the same 50 templates work
// whether the idea targets founders, HR managers, teachers, or anyone else.
type ChannelKey = 'linkedin' | 'twitter' | 'whatsapp' | 'reddit';
type ChannelMsgCfg = { mode: 'edited'; text: string };
type OutreachMsgConfig = {
  audienceOverride?: string;
  linkedin?: ChannelMsgCfg;
  twitter?: ChannelMsgCfg;
  whatsapp?: ChannelMsgCfg;
  reddit?: ChannelMsgCfg;
};

function articleFor(word: string): string {
  return /^[aeiouAEIOU]/.test(word) ? 'an' : 'a';
}
function singularizeAudience(label: string): string {
  const t = (label || 'people').trim() || 'people';
  const lower = t.toLowerCase();
  if (lower === 'people') return 'person';
  if (lower.endsWith('ies') && t.length > 3) return t.slice(0, -3) + 'y';
  if (lower.endsWith('s') && !lower.endsWith('ss')) return t.slice(0, -1);
  return t;
}
function renderAudienceTemplate(text: string, audienceLabel: string): string {
  const plural = (audienceLabel || 'people').trim() || 'people';
  const singular = singularizeAudience(plural);
  const art = articleFor(singular);
  return text
    .split('{AUDIENCE}').join(plural)
    .split('{Audience}').join(plural.charAt(0).toUpperCase() + plural.slice(1))
    .split('{AUDIENCE_ONE}').join(singular)
    .split('{A_AUDIENCE_ONE}').join(`${art} ${singular}`);
}

